mt19937 rng(7); Solution solver;
for (int trial=0; trial<1000; ++trial) {
    string s; for(int n=rng()%30;n--;)s+=char('a'+rng()%4);
    int best=0;
    for(int i=0;i<(int)s.size();++i)for(int j=i;j<(int)s.size();++j){
        bool ok=true;for(int l=i,r=j;l<r;++l,--r)if(s[l]!=s[r])ok=false;
        if(ok)best=max(best,j-i+1);
    }
    string answer=solver.longestPalindrome(s),reverse=answer;ranges::reverse(reverse);
    if(answer!=reverse || (int)answer.size()!=best || s.find(answer)==string::npos)throw runtime_error("palindrome oracle");
}

