 shuffle(positions.begin(),positions.end(),rng);positions.resize(min<int>(positions.size(),rng()%10));
 auto cuts=positions;positions.push_back(0);positions.push_back(length);ranges::sort(positions);int n=positions.size();
 vector<vector<int>> dp(n,vector<int>(n));
 for(int gap=2;gap<n;++gap)for(int i=0;i+gap<n;++i){int j=i+gap;dp[i][j]=INT_MAX;for(int k=i+1;k<j;++k)dp[i][j]=min(dp[i][j],dp[i][k]+dp[k][j]+positions[j]-positions[i]);}
 if(solver.minCost(length,cuts)!=dp[0][n-1])throw runtime_error("Knuth versus cubic DP");
