 for(int i=0;i<(int)a.size();++i)for(int j=i+1;j<(int)a.size();++j)for(int k=j;k<(int)a.size();++k){int x=0,y=0;for(int p=i;p<j;++p)x^=a[p];for(int p=j;p<=k;++p)y^=a[p];count+=x==y;}
