for(int capacity=0;capacity<=6;++capacity){LRUCache cache(capacity);vector<pair<int,int>> recent;
 for(int step=0;step<5000;++step){int key=rng()%12;auto it=find_if(recent.begin(),recent.end(),[&](auto x){return x.first==key;});
 if(rng()%2){int expected=it==recent.end()?-1:it->second;if(cache.get(key)!=expected)throw runtime_error("LRU get");if(it!=recent.end()){auto entry=*it;recent.erase(it);recent.insert(recent.begin(),entry);}}
 else {int value=rng()%1000;cache.put(key,value);if(it!=recent.end())recent.erase(it);if(capacity){recent.insert(recent.begin(),{key,value});if((int)recent.size()>capacity)recent.pop_back();}}}
