mt19937 rng(15);
for(int capacity=0;capacity<=6;++capacity){LFUCache cache(capacity);map<int,tuple<int,int,int>> reference;int clock=0;
 for(int step=0;step<5000;++step){++clock;int key=rng()%12;
 if(rng()%2){auto it=reference.find(key);int expected=it==reference.end()?-1:get<0>(it->second);if(cache.get(key)!=expected)throw runtime_error("LFU get");if(it!=reference.end()){++get<1>(it->second);get<2>(it->second)=clock;}}
 else {int value=rng()%1000;cache.put(key,value);if(!capacity)continue;auto it=reference.find(key);
 if(it!=reference.end()){get<0>(it->second)=value;++get<1>(it->second);get<2>(it->second)=clock;}
 else {if((int)reference.size()==capacity){auto victim=reference.begin();for(auto x=reference.begin();x!=reference.end();++x)if(pair{get<1>(x->second),get<2>(x->second)}<pair{get<1>(victim->second),get<2>(victim->second)})victim=x;reference.erase(victim);}reference[key]={value,1,clock};}}}
}

mt19937 rng(16);MyLinkedList list;vector<int> reference;
for(int step=0;step<20000;++step){int op=rng()%6,index=int(rng()%(reference.size()+4))-1,value=rng()%1000;
 if(op==0){list.addAtHead(value);reference.insert(reference.begin(),value);}
 if(op==1){list.addAtTail(value);reference.push_back(value);}
 if(op==2){list.addAtIndex(index,value);index=max(index,0);if(index<=(int)reference.size())reference.insert(reference.begin()+index,value);}
 if(op==3){list.deleteAtIndex(index);if(index>=0&&index<(int)reference.size())reference.erase(reference.begin()+index);}
 if(op>=4){int expected=index>=0&&index<(int)reference.size()?reference[index]:-1;if(list.get(index)!=expected)throw runtime_error("design linked list");}
}

