for(int trial=0;trial<500;++trial){int n=2+rng()%10;vector<vector<int>> edges;for(int v=1;v<n;++v)edges.push_back({v,int(rng()%v)});
 for(int a=0;a<n;++a)for(int b=a+1;b<n;++b)if(rng()%5==0&&none_of(edges.begin(),edges.end(),[&](auto e){return(e[0]==a&&e[1]==b)||(e[0]==b&&e[1]==a);}))edges.push_back({a,b});
 set<pair<int,int>> expected,actual;
 for(int removed=0;removed<(int)edges.size();++removed){vector<vector<int>>g(n);for(int e=0;e<(int)edges.size();++e)if(e!=removed){g[edges[e][0]].push_back(edges[e][1]);g[edges[e][1]].push_back(edges[e][0]);}vector<bool>seen(n);vector<int>stack{0};seen[0]=true;while(!stack.empty()){int u=stack.back();stack.pop_back();for(int v:g[u])if(!seen[v]){seen[v]=true;stack.push_back(v);}}if(count(seen.begin(),seen.end(),true)!=n)expected.emplace(min(edges[removed][0],edges[removed][1]),max(edges[removed][0],edges[removed][1]));}
 for(auto edge:solver.criticalConnections(n,edges))actual.emplace(min(edge[0],edge[1]),max(edge[0],edge[1]));if(actual!=expected)throw runtime_error("bridge deletion oracle");}
