for(int trial=0;trial<1000;++trial){int n=1+rng()%30,k=1+rng()%n,c=1+rng()%n;vector<int>costs(n);for(int&x:costs)x=1+rng()%30;vector<pair<int,int>>remaining;for(int i=0;i<n;++i)remaining.emplace_back(costs[i],i);long long expected=0;
